contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes: caller (simulated by using the test as caller), target value to withdraw,
    // and an amount to send into the contract via fallback. The checker deploys a fresh C
    // whose owner is the deployer (the checker), but calls from this contract will be non-owner.
    // We assert that non-owner withdraw attempts revert and do not change address(c).balance.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Initial observable balance of c
        uint beforeBal = address(c).balance;

        // Send Ether to c so its fallback increments depositsCount and increases balance
        // Note: fallback is payable and increments depositsCount
        c.fallback{value: depositAmount}();

        uint afterDepositBal = address(c).balance;

        // Ensure deposit had expected effect on balance (deposit increased by depositAmount)
        // This is a reachable assertion check later; but we don't assert it here as final.

        // Attempt withdraw and withdrawAll as this contract (which is NOT the owner of c)
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Read final observable state
        uint finalBal = address(c).balance;
        uint depositsCnt = c.depositsCount();

        // General rule asserted for all inputs:
        // If this contract (not owner) attempted withdraw or withdrawAll, those calls must revert
        // and the contract balance must not decrease as a result. Additionally, depositsCount
        // should have increased by exactly 1 due to the deposit call above.
        assert(
            // depositsCount increased by 1 compared to beforeBal (we infer before by final-beforeDeposit)
            depositsCnt >= 1 &&
            // The deposit increased the balance by exactly depositAmount
            afterDepositBal == beforeBal + depositAmount &&
            // If withdraw returned (did not revert), that's allowed only if it didn't change balance.
            // Otherwise (typical case) it reverted. So require that for both withdraw attempts,
            // if they reverted then finalBal == afterDepositBal; if they didn't revert they also
            // must not have decreased the contract balance.
            (withdrewReverted ? finalBal == afterDepositBal : finalBal >= afterDepositBal) &&
            (withdrewAllReverted ? finalBal == afterDepositBal : finalBal >= afterDepositBal)
        );
    }

    // Allow receiving ETH for this test contract to fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit and an attempted withdraw amount.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Read observable before-values
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Send Ether to c causing its payable fallback to run and increment depositsCount
        // We must call via address(c).call because fallback has no function name
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit call failed");

        uint afterDepositBal = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Attempt withdraw as this contract (which is NOT owner). Capture whether they reverted.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint finalBal = address(c).balance;

        // General rule asserted for all inputs:
        // 1) The deposit increased address(c).balance by exactly depositAmount and depositsCount by exactly 1.
        // 2) Any non-owner attempt to withdraw (withdraw or withdrawAll) must not decrease the contract balance.
        assert(
            afterDepositBal == beforeBal + depositAmount &&
            afterDeposits == beforeDeposits + 1 &&
            // finalBal must be at least afterDepositBal regardless of whether withdraw calls reverted
            finalBal >= afterDepositBal
        );
    }

    receive() external payable {}
}

