contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test sends an arbitrary amount to c (as non-owner) and then checks behavior.
    function run(uint sendAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to send");

        // Observe pre-state
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // send Ether to c to trigger fallback (deposit)
        c.f{value: sendAmount}("");

        // Observe post-state
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // Attempt owner-only actions as non-owner (this contract is NOT owner): they should revert.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(address(0x1234), withdrawAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // General rule:
        // - depositsCount increased by exactly 1
        // - c's balance increased by exactly sendAmount
        // - all owner-only actions reverted when called by this (non-owner) contract
        assert(afterCount == beforeCount + 1 && afterBal == beforeBal + sendAmount
               && withdrawReverted && withdrawAllReverted && sendMoneyReverted);
    }

    // Allow this test contract to receive Ether so it can fund sendAmount when invoked by the checker.
    receive() external payable {}
}

