contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test checks that when called by a non-owner (this contract), calls that would
    // transfer Ether out of C must revert and therefore do not change balances.
    function run(uint sendAmount, uint callValue) public payable {
        require(true);
        // Precondition: ensure this test contract has Ether to send into c if needed
        if (callValue > 0) {
            require(address(this).balance >= callValue, "insufficient balance to fund call");
            // Fund C by invoking its fallback to increment depositsCount and accept Ether
            c.f{value: callValue}();
        }

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrewReverted;
        try c.withdraw(sendAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendMoneyReverted;
        // attempt to make c call this contract (which would transfer out if allowed)
        try c.sendMoney(address(this), sendAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: since InvMutTest is not the owner of C (C.owner == deployer of C),
        // none of the attempted outgoing transfers from C should succeed; therefore if any
        // of the calls reverted it's allowed, but if any didn't revert then balances must
        // reflect that transfer (i.e., C lost Ether and this gained Ether). We assert the
        // stronger property: because this contract is not owner, none of the three calls
        // may succeed — equivalently afterC == beforeC and afterThis == beforeThis.
        assert(afterC == beforeC && afterThis == beforeThis);
    }

    // Allow receiving Ether for sendMoney fallback target
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test tries to perform outgoing transfers from C while not being the owner.
    // It first (optionally) funds C by calling its fallback via a plain call with value.
    // Then it tries withdrawAll(), withdraw(amount), and sendMoney(this, amount).
    // It asserts that after these attempts, balances of c and this contract are unchanged.
    function run(uint fundAmount, uint withdrawAmount) public payable {
        require(true);

        // If asked to fund C, ensure this contract has enough balance and send Ether to C
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // Call C with empty calldata to hit fallback and deposit Ether
            (bool ok,) = address(c).call{value: fundAmount}("");
            // Accept both success and failure of funding; state observation will reflect outcome
        }

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        bool revertedWithdraw;
        try c.withdraw(withdrawAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        bool revertedSendMoney;
        try c.sendMoney(address(this), withdrawAmount) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule: since this contract is not the owner of C, none of the three outgoing
        // transfer calls may succeed in taking Ether out of C. Therefore balances must be unchanged.
        // We assert this relation which must hold for all inputs.
        assert(afterC == beforeC && afterThis == beforeThis);
    }

    // Allow receiving Ether in case C.sendMoney tries to send to this contract.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send an amount to C (to trigger fallback) and check depositsCount increments by 1
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Top-level state-changing call: send Ether to C to invoke fallback
        (bool ok, ) = address(c).call{value: amount}("");
        // allow either success or failure; behavior is observable via getters

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if the low-level call succeeded and amount > 0 then fallback executed once,
        // so depositsCount increments by exactly 1 and C's balance increases by amount.
        // If the call failed or amount == 0, depositsCount and balance remain unchanged.
        assert( (ok && amount > 0 && afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount)
             || ((!ok || amount == 0) && afterCount == beforeCount && afterBalance == beforeBalance) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send an amount to C (to trigger fallback) and check depositsCount increments by 1
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Top-level state-changing call on c: use the low-level call via c itself is not possible,
        // but we must invoke C.fallback by calling C with value. According to constraints, calls
        // that change c's state must be top-level and on c. The only way to trigger fallback
        // is sending Ether to address(c) — do that as a plain top-level statement.
        (bool ok, ) = address(c).call{value: amount}("");

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if the low-level call succeeded and amount > 0 then fallback executed once,
        // so depositsCount increments by exactly 1 and C's balance increases by amount.
        // Otherwise (call failed or amount == 0) both remain unchanged.
        assert(
            (ok && amount > 0 && afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount)
            || ((!ok || amount == 0) && afterCount == beforeCount && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amount and a boolean flag 'doCall' to decide whether to invoke the low-level call.
    // The only state-changing interaction with C must be a top-level call on c; we accomplish
    // the external send to C by exposing a helper state change: we first call a no-op view to
    // read state, then perform the low-level call as a top-level statement via address(c).call.
    // However, to satisfy the constraint that EVERY state-changing call on c must be of the form
    // c.f(args) at top-level, we instead use c.sendMoney with target = address(c) and value = amount
    // to route a call from C to itself (this is a state-changing call on c and is top-level). That
    // will invoke C's sendMoney which uses _target.call{value:_value}(""); when target==address(c)
    // that triggers the fallback, incrementing depositsCount. This keeps the state-changing call
    // as a direct c.f(...) invocation.

    function run(uint amount, bool doCall) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool callSucceeded = false;
        // If caller requests no action, skip the state-changing call. Otherwise perform a top-level
        // state-changing call on c: c.sendMoney(address(c), amount);
        if (doCall) {
            // c.sendMoney is a public function and must be invoked as a top-level state-changing call.
            // It will internally perform address(c).call{value: amount}("") and thus may trigger
            // the fallback, incrementing depositsCount on success.
            // We capture whether sendMoney reverted by try/catch to get a boolean result.
            try c.sendMoney(address(c), amount) {
                callSucceeded = true;
            } catch {
                callSucceeded = false;
            }
        } else {
            callSucceeded = false;
        }

        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert): If we performed the call (doCall==true) and it returned
        // successfully (callSucceeded==true) and amount > 0, then depositsCount increments by 1
        // and C's balance increases by amount. Otherwise (no call, call failed, or amount==0)
        // both depositsCount and balance remain unchanged.
        assert(
            (doCall && callSucceeded && amount > 0 && afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount)
            || ((!doCall || !callSucceeded || amount == 0) && afterCount == beforeCount && afterBalance == beforeBalance)
        );
    }

    // allow receiving Ether if C sends back funds to this contract in the test
    receive() external payable {}
}

contract InvMutTest {
