    // amount: Ether sent when invoking fallback or sendMoney; sendCall: 0 = don't call sendMoney, 1 = call sendMoney; doWithdraw: 0 = don't call withdraw, 1 = call withdrawAll
    function run(uint amount, uint sendCall, uint doWithdraw) public payable {
        require(amount <= address(this).balance, "insufficient balance for amount");
        // Read observable before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        // 1) trigger fallback by sending Ether to c (this will increment depositsCount on successful call)
        // Note: c.fallback is payable and increments depositsCount. We perform it by calling with value.
        if (amount > 0) {
            // top-level state-changing call
            (bool sent,) = address(c).call{value: amount}("");
            // We don't revert the whole test on this; record whether it succeeded by reading state below.
        }

        // 2) attempt to call sendMoney from this contract (which is not the original owner of C), possibly sending value
        bool sendReverted;
        if (sendCall == 1) {
            try c.sendMoney(address(0x1234), amount) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        } else {
            sendReverted = false; // no-op
        }

        // 3) attempt withdrawAll which should revert for non-owner
        bool withdrawReverted;
        if (doWithdraw == 1) {
            try c.withdrawAll() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = false;
        }

        // Read observable after-state
        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: If this contract is not the owner (it isn't, since owner was set to C's deployer),
        // then any attempt to call withdraw or sendMoney from this caller must revert, and whether or not fallback succeeded,
        // the only permitted change is depositsCount increasing by the Ether-sending fallback; balance of c should only change by that amount.
        // Expressed as: if withdraw/sendMoney were invoked, they must have reverted; and the difference in c.balance equals (afterDeposits - beforeDeposits) * amount_when_fallback_called.
        // We don't have direct per-call amount, but the only value that could change c.balance in our interactions is the initial amount sent via the fallback call.

        // Formulate the assertion:
        // - If sendCall==1 then sendReverted must be true
        // - If doWithdraw==1 then withdrawReverted must be true
        // - The change in c.balance equals at most amount (since only the fallback could have increased it by exactly amount on success), and depositsCount increases by either 0 or 1 matching that change.

        // Implement the assertion combining these conditions.
        assert((sendCall != 1 || sendReverted == true)
            && (doWithdraw != 1 || withdrawReverted == true)
            && (afterBal >= beforeBal) // balance cannot decrease because non-owner calls cannot withdraw
            && (afterBal - beforeBal <= amount)
            && (uint(afterDeposits - beforeDeposits) <= 1)
            && ((afterBal - beforeBal == 0 && afterDeposits - beforeDeposits == 0) || (afterBal - beforeBal == amount && afterDeposits - beforeDeposits == 1))
        );
    }

    // Allow receiving Ether when C sends back funds (not expected for non-owner)
    receive() external payable {}
}

