        uint depositsAfter = c.depositsCount();
        uint balAfter = address(c).balance;

        bool isOwner = (ownerBefore == address(this));

        // If sendMoney to self reverted then fallback wasn't invoked via that call; the only guaranteed change is owner unchanged.
        // General rule asserted:
