    constructor(C _c) { c = _c; }

    // Single public entry that drives c and asserts a general invariant
    // params:
    //   sendToC1, sendToC2: amounts this test will attempt to send into c by invoking c.sendMoney to address(c)
    //   target: an arbitrary address used for a sendMoney call
    //   sendToTarget: amount used when calling c.sendMoney(target, sendToTarget)
    function run(uint sendToC1, uint sendToC2, address payable target, uint sendToTarget) public payable {
        // ensure this contract has enough balance to fund the attempted sends into c
        require(address(this).balance >= sendToC1 + sendToC2 + sendToTarget, "insufficient balance");

        // Observe initial public state
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balBefore = address(c).balance;

        // First attempt: ask c to call itself with sendToC1 value (may revert if not owner)
        bool call1Reverted;
        try c.sendMoney(payable(address(c)), sendToC1) {
            call1Reverted = false;
        } catch {
            call1Reverted = true;
        }

        // Second attempt: ask c to call an external target with sendToTarget (may revert if not owner)
        bool callTargetReverted;
        try c.sendMoney(target, sendToTarget) {
            callTargetReverted = false;
        } catch {
            callTargetReverted = true;
        }

        // Third attempt: ask c to call itself again with sendToC2 value
        bool call2Reverted;
        try c.sendMoney(payable(address(c)), sendToC2) {
            call2Reverted = false;
        } catch {
            call2Reverted = true;
        }

        // Observe after-values
        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint balAfter = address(c).balance;

        // Count how much Ether actually made it into c from our two self-calls: each successful sendMoney to address(c)
        // causes c to perform an external call to itself with value; if that top-level sendMoney call did not revert then
        // the Ether was forwarded into c (even if the inner fallback reverts, that would have caused the outer call to revert).
        uint netSentToC = 0;
        if (!call1Reverted) { netSentToC += sendToC1; }
        if (!call2Reverted) { netSentToC += sendToC2; }

        // General invariant to hold for all inputs and behaviors:
        // 1) owner never changes
        // 2) depositsCount never decreases (can't go below previous value)
        // 3) c.balance increased exactly by the net Ether that successfully entered c via the two attempted self-sends
        assert(
            ownerBefore == ownerAfter &&
            depositsAfter >= depositsBefore &&
            balAfter == balBefore + netSentToC
        );
    }

    // Allow receiving Ether when c calls back to this contract
    receive() external payable {}
}

