        // Fund C so there is balance to withdraw. We must ensure this contract has enough balance to send amount.
        if (address(this).balance >= amount) {
            // send amount to c by calling its fallback via a direct call with empty data
            (bool s, ) = address(c).call{value: amount}("");
            // we don't require success; fallback increments depositsCount when receiving.
            s; // silence unused warning
        }

