    C c;
    constructor(C _c) { c = _c; }

    // Run a single low-level call to c with arbitrary calldata and value.
    // Parameters:
    //   bytes calldataData - the calldata sent in the low-level call
    //   uint amount - amount of wei to send with the call
    function run(bytes calldataData, uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Perform the low-level call directly to C with the provided calldata and value.
        (bool ok, ) = address(c).call{value: amount}(calldataData);
        bool reverted = !ok;

        // Observe after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule:
        // - If calldataData is empty and the call succeeded, fallback should have executed once: depositsCount increases by 1 and balance increases by amount.
        // - If calldataData is non-empty, fallback must not run; depositsCount must be unchanged, and if the call succeeded balance increases by amount (but depositsCount stays same).
        // - If the call reverted, state is unchanged (depositsCount and balance remain as before).
        assert(
            // reverted => unchanged
            (reverted && afterCount == beforeCount && afterBal == beforeBal)
            ||
            // success and empty calldata => fallback ran exactly once
            (!reverted && calldataData.length == 0 && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
            ||
            // success and non-empty calldata => fallback did NOT run, only balance may increase
            (!reverted && calldataData.length != 0 && afterCount == beforeCount && afterBal == beforeBal + amount)
        );
    }

    // Allow receiving Ether so the test can forward funds to c
    receive() external payable {}
}

