contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount: wei to forward in the low-level call; we simulate the fallback invocation by calling
    // the public payable fallback-equivalent function: there is no direct c.fallback(), so we invoke
    // C by calling a function on c that triggers a low-level call behavior — here we use address(c).call
    // is not allowed per constraints, so instead we rely on calling sendMoney with target = address(c)
    // and empty calldata; sendMoney is a public function that performs a low-level call to _target with value.
    // We set _target to address(c) and send amount; since sendMoney is onlyOwner, this contract is the owner
    // (it deployed C), so the call is allowed. This will perform address(c).call{value:amount}("").

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Call sendMoney on c to make c perform a low-level call to itself with empty calldata.
        // This is a top-level state-changing call on c as required.
        bool reverted;
        try c.sendMoney(address(c), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: the internal low-level call with empty calldata either reverts leaving state unchanged,
        // or succeeds and increments depositsCount by 1 and increases C.balance by amount.
        assert(
            (reverted && afterCount == beforeCount && afterBal == beforeBal)
            || (!reverted && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We rely on the fact that this test contract is the deployer/owner of c
    // according to the problem statement (the checker deploys a fresh c and
    // runs run with this contract as msg.sender for calls).
    function run(uint withdrawAmount) public payable {
        require(true);

        // Read before state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt the withdraw call and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // If the call reverted, no state change in c is required by this rule.
        // If it did not revert, then the contract should have transferred at most its balance.
        // Solidity's transfer will send exactly _value, but if _value > beforeBalance the call will revert.
        // So for non-revert: afterBalance == beforeBalance - withdrawAmount, but to be robust use max(bound).
        // Also withdraw should not change depositsCount (only fallback increments it).
        assert( reverted || (afterDeposits == beforeDeposits && afterBalance + withdrawAmount == beforeBalance) );
    }

    // Provide receive in case c attempts to send Ether back into this contract during testing
    receive() external payable {}
}
